def orfs(s, name, minaa=50):
    stops = {"TAA","TAG","TGA"}
    res=[]
    for frame in range(3):
        i=frame
        start=None
        aa=0
        pos=frame
        while pos+3<=len(s):
            cod=s[pos:pos+3]
            if cod=="ATG" and start is None:
                start=pos
            if cod in stops:
                if start is not None:
                    L=pos+3-start
                    if L>=minaa*3:
                        res.append((name,frame+1,start+1,pos+3,L,L//3))
                start=None
            pos+=3
        # trailing ORF no stop
        if start is not None:
            L=len(s)-start
            if L>=minaa*3:
                res.append((name,frame+1,start+1,len(s),L,L//3,"no-stop"))
    return res

