seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
comp = str.maketrans("ACGT","TGCA")
rc = seq.translate(comp)[::-1]

# palindrome search: find longest reverse-complement match centered at each position
best=[]
for i in range(len(seq)):
    # expand
    k=0
    while i-k>=0 and i+k<len(seq) and seq[i-k]==rc[i+k]:
        k+=1
    L=2*k-1  # odd-length palindrome centered at i (including center)
    best.append((L, i-(k-1)+1, i+k))  # 1-based start,end
best.sort(reverse=True)
print("longest odd palindromes (1-based):")
for L,a,b in best[:6]:
    print(L, a, b, seq[a-1:b])

# even palindromes (stem length)
best2=[]
for i in range(len(seq)-1):
    k=0
    # center between i and i+1
    while i-k>=0 and i+1+k<len(seq) and seq[i-k]==rc[i+1+k]:
        k+=1
    L=2*k
    best2.append((L, i-k+1+1, i+1+k))
best2.sort(reverse=True)
print("longest even palindromes (1-based):")
for L,a,b in best2[:6]:
    print(L, a, b, seq[a-1:b])

